import {buildings,nearby,formatDistance} from './data.js';
const b=buildings.find(b=>b.id===new URLSearchParams(location.search).get('id'))||buildings[0];
document.title=`${b.name} · Itapema Vista`;document.getElementById('return').href=`index.html#/${b.id}`;
const titles={brisa:'A natureza encontra o seu endereço.',vista:'A cidade aos seus pés.',horizonte:'Um novo olhar para o mar.',atlantico:'Viva o horizonte por inteiro.'};
document.getElementById('product').innerHTML=`<section class="hero"><img src="renders/architecture/${b.id}-hero.webp" alt="Perspectiva ilustrativa de ${b.name}"><div class="hero-copy"><span>${b.region} · Itapema, SC</span><h1>${b.name}</h1><p>${titles[b.id]}</p><a class="button" href="#conceito">Conheça o conceito ↓</a></div><small class="image-note">Imagem ilustrativa · empreendimento fictício</small></section><section id="conceito" class="intro"><span class="kicker">UM LUGAR PARA IMAGINAR</span><h2>${titles[b.id]}</h2><p>${b.description}</p><div class="facts"><div><strong>${b.floors}</strong><span>pavimentos no conceito</span></div><div><strong>Itapema</strong><span>Santa Catarina</span></div><div><strong>01</strong><span>nova perspectiva</span></div></div></section><section class="living"><div><span class="kicker">ARQUITETURA & PAISAGEM</span><h2>O entorno também<br>faz parte de casa.</h2><p>Varandas, luz natural e paisagismo compõem este estudo arquitetônico. Explore a região e descubra a proximidade dos pontos turísticos de Itapema.</p><a class="button dark" href="index.html#/${b.id}">Explorar a região ↗</a></div><img loading="lazy" src="renders/architecture/${b.id}-hero.webp" alt="Estudo arquitetônico ${b.name}"></section><section class="surroundings"><div><span class="kicker">ITAPEMA POR PERTO</span><h2>Seus próximos<br>lugares favoritos.</h2><p>Distâncias aproximadas em linha reta a partir da posição de teste. Toque em um destino para consultar o trajeto no Google Maps.</p><a class="button dark" href="mapa.html#${b.id}">Ver localização no mapa ↗</a></div><div class="places">${nearby(b).map(p=>`<a href="https://www.google.com/maps/dir/?api=1&origin=${b.coords[1]},${b.coords[0]}&destination=${p.coords[1]},${p.coords[0]}" target="_blank" rel="noopener"><span><small>${p.category}</small>${p.name}</span><strong>${formatDistance(p.distance)} ↗</strong></a>`).join('')}</div></section><section class="closing"><span class="kicker">${b.name.toUpperCase()}</span><h2>Comece pela paisagem.</h2><a class="button" href="index.html#/${b.id}">Voltar ao empreendimento ↗</a><p>Produto de demonstração, sem oferta comercial, unidades ou preços disponíveis.</p></section>`;
